    def _validate_handoff_temporal_lineage(
        db: Session,
        *,
        upload_run_id: int,
        market_cutoff: MarketCalculationCutoff,
        ceri_market_cutoff: MarketCalculationCutoff | None = None,
        built_rows,
        checkpoint_callback=None,
    ) -> None:
        ceri_cutoff = ceri_market_cutoff or market_cutoff
        failures: list[str] = []
        price_bars = []
        calculation_context = db.get(MarketCalculationContext, market_cutoff.context_id)
        pipeline_run_id = getattr(calculation_context, "pipeline_run_id", None)
        total = len(built_rows)
        for index, (context, _built) in enumerate(built_rows, start=1):
            ticker = context.ticker
            raw = context.raw_row
            fundamental = context.fundamental_score
            technical = context.technical_score
            combined = context.combined_result
            market = context.market_regime_snapshot
            sector = context.sector_rotation_snapshot
            if raw.run_id != upload_run_id:
                failures.append(f"{ticker}:raw_run")
            if fundamental is not None and (
                fundamental.run_id != upload_run_id or fundamental.ticker.upper() != ticker
            ):
                failures.append(f"{ticker}:fundamental_run")
            if technical is None:
                failures.append(f"{ticker}:technical_missing")
            elif not _temporal_artifact_matches(technical, market_cutoff, upload_run_id):
                failures.append(f"{ticker}:technical_cutoff")
            if combined is not None:
                if combined.run_id != upload_run_id or combined.ticker.upper() != ticker:
                    failures.append(f"{ticker}:combined_run")
                expected_sources = {
                    "raw_row_id": raw.id,
                    "fundamental_score_id": getattr(fundamental, "id", None),
                    "technical_score_id": getattr(technical, "id", None),
                }
                observed_sources = dict((combined.debug_json or {}).get("source_ids") or {})
                if getattr(combined, "evidence_id", None) is not None or any(
                    key.endswith("_evidence_id") for key in observed_sources
                ):
                    from app.services.core_calculation_evidence import (
                        CoreEvidenceKind,
                        get_certified_evidence_for_row,
                    )

                    # Certified Combined proof pins immutable source evidence; score
                    # projection IDs can change on an exact retry. Verify both the
                    # retained graph and the supplied upstream evidence pointers.
                    evidence = get_certified_evidence_for_row(
                        db, kind=CoreEvidenceKind.COMBINED, current_row=combined
                    )
                    from app.models.tables import CoreCalculationEvidence

                    if isinstance(evidence, CoreCalculationEvidence):
                        from app.services.core_mutation_authority import (
                            _validate_evidence,
                            validate_source_values,
                        )

                        _validate_evidence(evidence)
                        validate_source_values(combined, evidence, db=db)
                        # Native blocked-input decisions can clear compatibility
                        # score IDs. The immutable graph retains the actual upstream
                        # evidence, including inputs evaluated and then blocked.
                        observed_sources = dict(
                            (evidence.payload_json.get("debug_json") or {}).get("source_ids") or {}
                        )
                    expected_pins = {
                        role: source.evidence_id
                        for role, source in (("fundamental", fundamental), ("technical", technical))
                        if source is not None and source.evidence_id is not None
                    }
                    expected_sources = {
                        "raw_row_id": raw.id,
                        **{role + "_evidence_id": address for role, address in expected_pins.items()},
                    }
                    if evidence is None or evidence.source_evidence_ids_json != expected_pins:
                        failures.append(f"{ticker}:combined_evidence_sources")
                if observed_sources != expected_sources:
                    failures.append(f"{ticker}:combined_sources")
            for ranking in context.ranking_results:
                if (
                    ranking.run_id != upload_run_id
                    or ranking.ticker.upper() != ticker
                    or ranking.raw_row_id != raw.id
                ):
                    failures.append(f"{ticker}:ranking_sources")
            for definition in REQUIRED_HANDOFF_CONTEXT_ARTIFACTS:
                try:
                    validate_required_handoff_context_artifact(
                        getattr(context, definition.key),
                        definition=definition,
                        ticker=ticker,
                        upload_run_id=upload_run_id,
                        pipeline_run_id=pipeline_run_id,
                        calculation_context_id=market_cutoff.context_id,
                        cutoff_at=market_cutoff.cutoff_at,
                        input_as_of_session=market_cutoff.latest_completed_session,
                        calendar_version=market_cutoff.calendar_version,
                    )
                except RequiredHandoffArtifactError as exc:
                    failures.append(str(exc))
            if sector is not None and market is not None:
                if sector.market_regime_snapshot_id != market.id:
                    failures.append(f"{ticker}:sector_market_parent")
            if context.sector_rotation_row is not None and (
                sector is None or context.sector_rotation_row.snapshot_id != sector.id
            ):
                failures.append(f"{ticker}:sector_row_parent")
            price_bars.extend(context.price_bars)
            if checkpoint_callback is not None and (index % 25 == 0 or index == total):
                checkpoint_callback(
                    phase="TEMPORAL_LINEAGE_VALIDATED",
                    processed=index,
                    total=total,
                    current_item=ticker,
                    last_completed_item=ticker,
                )

        for bar in invalid_price_bar_rows_for_context(
            db,
            price_bars,
            max_session=market_cutoff.latest_completed_session,
            as_of=market_cutoff.cutoff_at,
            calculation_context_id=market_cutoff.context_id,
        ):
            failures.append(f"{bar.ticker.upper()}:post_cutoff_bar")

        ceri_rows = list(
            db.scalars(
                eligible_snapshot_select(name="effective_handoff_validation_dispositions").where(
